1	// Test helpers: start server.mjs as a child process and talk HTTP to it.
2	import { spawn } from 'node:child_process';
3	import { mkdtemp, writeFile } from 'node:fs/promises';
4	import { request as httpRequest } from 'node:http';
5	import { connect, createServer as createNetServer } from 'node:net';
6	import { tmpdir } from 'node:os';
7	import { dirname, join } from 'node:path';
8	import { fileURLToPath } from 'node:url';
9	
10	export const ROOT = join(dirname(fileURLToPath(import.meta.url)), '..', '..');
11	export const SERVER = join(ROOT, 'server.mjs');
12	export const LISTEN_RE = /^listening on http:\/\/127\.0\.0\.1:(\d+)\n$/;
13	export const JSON_TYPE = 'application/json; charset=utf-8';
14	export const JSON_HEADERS = Object.freeze({ 'Content-Type': 'application/json' });
15	const EXIT_TIMEOUT_MS = 5000;
16	
17	/** A valid booking body; override any field. */
18	export const booking = (overrides = {}) => ({
19	  room: 'Aurora',
20	  title: 'Standup',
21	  date: '2026-11-03',
22	  start: '09:00',
23	  end: '10:00',
24	  ...overrides,
25	});
26	
27	export const makeTmpDir = () => mkdtemp(join(tmpdir(), 'rooms-test-'));
28	
29	/** Writes a data file in the server's layout. */
30	export const writeStore = (path, bookings = [], nextId = bookings.length + 1) =>
31	  writeFile(path, JSON.stringify({ nextId, bookings }));
32	
33	/** Environment without the caller's PORT / DATA_FILE; `undefined` values mean unset. */
34	function buildEnv(env) {
35	  const base = { ...process.env };
36	  delete base.PORT;
37	  delete base.DATA_FILE;
38	  const merged = { ...base, ...env };
39	  return Object.fromEntries(Object.entries(merged).filter(([, v]) => v !== undefined));
40	}
41	
42	/** Spawns the server. Returns a handle with live stdout/stderr text and an exit promise. */
43	export function spawnServer({ cwd, env = {}, script = SERVER }) {
44	  const child = spawn(process.execPath, [script], { cwd, env: buildEnv(env) });
45	  const out = { stdout: '', stderr: '' };
46	  child.stdout.setEncoding('utf8').on('data', (d) => (out.stdout += d));
47	  child.stderr.setEncoding('utf8').on('data', (d) => (out.stderr += d));
48	  const exited = new Promise((resolve) => {
49	    child.on('close', (code, signal) => resolve({ code, signal }));
50	  });
51	  return {
52	    child,
53	    exited,
54	    stdout: () => out.stdout,
55	    stderr: () => out.stderr,
56	  };
57	}
58	
59	/** Runs the server until it exits by itself; fails if it is still running after the timeout. */
60	export async function runToExit(opts, timeoutMs = EXIT_TIMEOUT_MS) {
61	  const handle = spawnServer(opts);
62	  let timer;
63	  const timeout = new Promise((resolve) => {
64	    timer = setTimeout(() => resolve('timeout'), timeoutMs);
65	  });
66	  const result = await Promise.race([handle.exited, timeout]);
67	  clearTimeout(timer);
68	  if (result === 'timeout') {
69	    handle.child.kill('SIGKILL');
70	    await handle.exited;
71	    throw new Error(`server did not exit; stdout=${JSON.stringify(handle.stdout())}`);
72	  }
73	  return { code: result.code, signal: result.signal, stdout: handle.stdout(), stderr: handle.stderr() };
74	}
75	
76	/**
77	 * Starts the server (PORT=0 unless given) and waits for the listening line.
78	 * Returns { port, stop(), stdout(), stderr(), child }.
79	 */
80	export async function startServer({ cwd, env = {} }) {
81	  const handle = spawnServer({ cwd, env: { PORT: '0', ...env } });
82	  const port = await new Promise((resolve, reject) => {
83	    const onData = () => {
84	      const match = LISTEN_RE.exec(handle.stdout());
85	      if (match) resolve(Number(match[1]));
86	    };
87	    handle.child.stdout.on('data', onData);
88	    handle.exited.then(({ code }) =>
89	      reject(new Error(`server exited (${code}) before listening: ${handle.stderr()}`)),
90	    );
91	  });
92	  const stop = async () => {
93	    if (handle.child.exitCode === null && handle.child.signalCode === null) {
94	      handle.child.kill();
95	    }
96	    await handle.exited;
97	  };
98	  return { ...handle, port, stop };
99	}
