1	// Builds .team/near-miss/<n>-<file> copies, swaps each in, runs the suite, always restores.
2	// Usage: node .team/scratch/near-miss-run.mjs [make|run] [n,n,...]
3	import { spawnSync } from 'node:child_process';
4	import { createHash } from 'node:crypto';
5	import { existsSync, mkdirSync, readFileSync, readdirSync, rmSync, writeFileSync } from 'node:fs';
6	import { join } from 'node:path';
7	import { NEAR_MISSES, TARGETS } from './near-miss-defs.mjs';
8	
9	const ROOT = join(import.meta.dirname, '..', '..');
10	const DIR = join(ROOT, '.team', 'near-miss');
11	const BACKUP = join(ROOT, '.team', 'scratch', 'originals');
12	const sha = (buf) => createHash('sha256').update(buf).digest('hex');
13	const out = (line) => process.stdout.write(`${line}\n`);
14	
15	function comment(file, bug) {
16	  return file.endsWith('.html') ? `<!-- near-miss: ${bug} -->\n` : `// near-miss: ${bug}\n`;
17	}
18	
19	function make() {
20	  mkdirSync(DIR, { recursive: true });
21	  for (const [n, file, bug, edits] of NEAR_MISSES) {
22	    let text = readFileSync(join(ROOT, TARGETS[file]), 'utf8');
23	    for (const [from, to] of edits) {
24	      const count = text.split(from).length - 1;
25	      if (count !== 1) throw new Error(`near-miss ${n}: edit found ${count} times: ${from.slice(0, 60)}`);
26	      text = text.replace(from, () => to);
27	    }
28	    writeFileSync(join(DIR, `${n}-${file}`), comment(file, bug) + text);
29	  }
30	  out(`made ${NEAR_MISSES.length} near-miss copies`);
31	}
32	
33	function runOne(n, file) {
34	  const target = join(ROOT, TARGETS[file]);
35	  const original = readFileSync(target);
36	  const originalSha = sha(original);
37	  const hadRootStore = existsSync(join(ROOT, 'bookings.json'));
38	  let status;
39	  try {
40	    writeFileSync(target, readFileSync(join(DIR, `${n}-${file}`)));
41	    const res = spawnSync(process.execPath, ['--test', '--test-timeout=30000', '--test-reporter=dot', ...testFiles()], {
42	      cwd: ROOT, encoding: 'utf8', timeout: 300000,
43	    });
44	    status = res.status;
45	  } finally {
46	    writeFileSync(target, original);
47	    // A near-miss may write files next to server.mjs; remove what the run created.
48	    if (!hadRootStore) rmSync(join(ROOT, 'bookings.json'), { force: true });
49	  }
50	  if (sha(readFileSync(target)) !== originalSha) throw new Error(`RESTORE FAILED for ${target}`);
51	  return status;
52	}
53	
54	const testFiles = () => readdirSync(join(ROOT, 'test')).filter((f) => f.endsWith('.test.mjs')).map((f) => join('test', f));
55	
56	function run(only) {
57	  mkdirSync(BACKUP, { recursive: true });
58	  for (const file of Object.keys(TARGETS)) writeFileSync(join(BACKUP, file), readFileSync(join(ROOT, TARGETS[file])));
59	  const survivors = [];
60	  for (const [n, file, bug] of NEAR_MISSES) {
61	    if (only && !only.includes(n)) continue;
62	    const status = runOne(n, file);
63	    const caught = status !== 0;
64	    if (!caught) survivors.push(n);
65	    out(`${caught ? 'caught  ' : 'SURVIVED'} ${n}-${file}: ${bug} (exit ${status})`);
66	  }
67	  out(`survivors: ${survivors.length ? survivors.join(',') : 'none'}`);
68	  for (const file of Object.keys(TARGETS)) {
69	    const same = sha(readFileSync(join(BACKUP, file))) === sha(readFileSync(join(ROOT, TARGETS[file])));
70	    out(`original ${TARGETS[file]} ${same ? 'restored (sha256 match)' : 'MISMATCH'}`);
71	  }
72	}
73	
74	const [mode = 'run', list] = process.argv.slice(2);
75	if (mode === 'make') make();
76	else run(list ? list.split(',').map(Number) : null);
